/**
 * Toaster – the container that shows toast notifications ("Added to cart", errors…).
 *
 * Generated by shadcn/ui, then simplified: the original read the theme from
 * `next-themes` (dark-mode support). Dark mode is out of scope for the POC,
 * so we always use the light theme and avoid an extra dependency.
 *
 * Usage anywhere in the app:  import { toast } from 'sonner'; toast.success('Saved')
 * The <Toaster /> itself is mounted once, in App.tsx.
 */
import { Toaster as Sonner, type ToasterProps } from "sonner"
import { CircleCheckIcon, InfoIcon, TriangleAlertIcon, OctagonXIcon, Loader2Icon } from "lucide-react"

const Toaster = ({ ...props }: ToasterProps) => {
  return (
    <Sonner
      theme="light"
      className="toaster group"
      icons={{
        success: <CircleCheckIcon className="size-4 text-success" />,
        info: <InfoIcon className="size-4" />,
        warning: <TriangleAlertIcon className="size-4 text-warning" />,
        error: <OctagonXIcon className="size-4 text-danger" />,
        loading: <Loader2Icon className="size-4 animate-spin" />,
      }}
      style={
        {
          "--normal-bg": "var(--popover)",
          "--normal-text": "var(--popover-foreground)",
          "--normal-border": "var(--border)",
          "--border-radius": "var(--radius)",
        } as React.CSSProperties
      }
      {...props}
    />
  )
}

export { Toaster }
